import sys

from cc_term import supports_colour

CODES = {"red": 31, "green": 32, "yellow": 33}


def paint(text, colour, stream=None):
    stream = stream or sys.stdout
    if not supports_colour(stream):
        return text
    return f"\033[{CODES[colour]}m{text}\033[0m"

